function classification(e){const purpose=e&&evidencePurpose(e);return purpose?'purpose_'+purpose:e?.grade==='A'?'annotationRNA':e?.grade==='B'?'referenceRNA':e?.grade==='C'?'functional':'candidate';}
// Preview order is a navigation choice, never an evidence grade or confidence score.
function previewTags(m){const relationGroups=[new Set(['RNA_peak_in','used_as_scRNA_marker_for','published_expression_signature','source_cluster_marker','member_of_RNA_reference_module','RNA_program_context','scRNA_heterogeneity_example','scRNA_state_association','population_RNA_association','population_RNA_protein_association','stable_in_tested_conditions','counterevidence_to_universal_stability','enriched_in_context','induced_in_context','published_bulk_RNA_posttranscriptional_class','published_scrna_coexpression_module','promoter_noise_evolution_evidence','source_differential_RNA','source_named_state_RNA','source_continuous_RNA_association']),new Set(['regulatory_target_set']),new Set(['regulates_process','function_or_state_association','source_functional_set']),new Set(['GO_slim_function']),new Set(['protein_localization_context','genomic_context'])];const generic=new Set(['核心整理种子','SGD功能注释','GO功能注释','周期候选']);const order=tag=>{if(generic.has(tag))return 9;const es=values(m,'evidence').filter(e=>e.tag===tag);const found=relationGroups.findIndex(group=>es.some(e=>group.has(e.relation)));return found<0?6:found;};return values(m,'tags').map((tag,i)=>({tag,i,order:order(tag)})).sort((a,b)=>a.order-b.order||a.i-b.i).map(x=>x.tag);}
function evidenceTags(m,limit){const tags=values(m,'tags'),rows=limit?tags.slice(0,limit):tags;return `<div class="mw-evidence-tags">${rows.map(tag=>{const es=values(m,'evidence').filter(e=>e.tag===tag),grades=[...new Set(es.map(e=>e.grade))].sort(),label=grades.length?grades.join('/'):'·';return `<button type="button" class="mw-evidence-tag ${es.length?'has-evidence':'catalogue-tag'}" data-mw="evidence" data-id="${E(m.id)}" data-tag="${E(tag)}" title="${E(T('evidenceTitle')+' · '+X(tag))}"><span>${E(X(tag))}</span><b>${label}</b>${icon('external')}</button>`;}).join('')}</div>`;}
function goPreview(m){const slim=!!GO_SLIM_ASPECT[ui.evidenceBranch];if(!GO_ASPECT[ui.evidenceBranch]&&!slim)return '';const es=slim?evidenceMatches(m):null,gs=[...new Map(goRows(m).filter(g=>!es||es.some(e=>e.goId===g.id&&(!g.sourceId||g.sourceId===e.sourceId))).map(g=>[g.id,g])).values()];return `<div class="mw-go-preview"><span>${T(slim?'matchingGOSlim':'matchingGO')}</span>${gs.slice(0,3).map(g=>button(slim?'go-slim-evidence':'go-evidence',`${E(g.term)} <small>${E(g.id)}</small>`,`data-id="${E(m.id)}" data-go="${E(g.id)}"`,'mw-go-preview-tag')).join('')}${gs.length>3?`<small>+ ${gs.length-3}</small>`:''}</div>`;}
