function evidenceSourceLinks(e){const src=source(e.sourceId),extracted=source(e.extractionSourceId),links=new Map();const add=(url,label)=>{if(url&&!links.has(url))links.set(url,label)};add(e.sourceUrl||src?.paperUrl||src?.url,src?.paperTitle||src?.title||sourceName(e.sourceId));add(src?.url,src?.title||sourceName(e.sourceId));if(extracted)add(extracted.url,extracted.title||sourceName(e.extractionSourceId));return [...links].map(([url,label])=>`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">${icon('source')}${E(label)}${icon('external')}</a>`).join('');}
