const IMPORT_ID_HEADERS=new Set(['id','gene','genes','symbol','genesymbol','genename','geneid','geneidentifier','standardname','standardgenename','systematic','systematicid','systematicname','systematicorf','systematicgenename','orf','orfid','orfname','locus','locusid','featureid','sgd','sgdid','sgdidentifier','sgdaccession','primarysgdid','alias','genealias','基因','基因名','基因名称','基因符号','基因id','系统名','系统名称','系统orf','sgd编号','nomdugene','symboledugene','identifiantdugene','gen','nombredegen','simbolodelgen','idgen','genearenizena','geneikurra','geneidentifikatzailea']);
